const mn_limits = [_][2]usize{
    .{ 7, 7 },
    .{ 7, 16 },
    .{ 7, 33 },
    .{ 16, 7 },
    .{ 16, 16 },
    .{ 16, 33 },
    .{ 33, 7 },
    .{ 33, 16 },
    .{ 33, 33 },
};

test "zsl.matrix.apply2" {
    @setEvalBranchQuota(1_000_000);

    const allocator = std.testing.allocator;

    var prng = std.Random.DefaultPrng.init(@bitCast(std.Io.Clock.real.now(std.testing.io).toSeconds()));
    const rand = prng.random();

    inline for (combinations) |fake_combination| {
        inline for (mn_limits) |mn| {
            comptime var combination = fake_combination;
            inline for (0..combination.len) |i| {
                if (comptime !zsl.meta.isNumeric(combination[i]) and @hasDecl(combination[i], "instantiate")) {
                    if (@hasDecl(combination[i], "general"))
                        combination[i] = zsl.matrix.general.Static(mn[0], mn[1], combination[i].Numeric, combination[i].storage_layout)
                    else if (@hasDecl(combination[i], "symmetric"))
                        combination[i] = zsl.matrix.symmetric.Static(mn[0], combination[i].Numeric, combination[i].storage_uplo, combination[i].storage_layout)
                    else if (@hasDecl(combination[i], "hermitian"))
                        combination[i] = zsl.matrix.hermitian.Static(mn[0], combination[i].Numeric, combination[i].storage_uplo, combination[i].storage_layout)
                    else if (@hasDecl(combination[i], "triangular"))
                        combination[i] = zsl.matrix.triangular.Static(mn[0], mn[1], combination[i].Numeric, combination[i].storage_uplo, combination[i].storage_diag, combination[i].storage_layout)
                    else if (@hasDecl(combination[i], "diagonal"))
                        combination[i] = zsl.matrix.diagonal.Static(mn[0], mn[1], combination[i].Numeric)
                    else if (@hasDecl(combination[i], "permutation"))
                        combination[i] = zsl.matrix.permutation.Static(mn[0], combination[i].Numeric, combination[i].storage_direction);
                }
            }

            if (comptime !((zsl.meta.isSquareMatrix(combination[0]) or
                zsl.meta.isSquareMatrix(combination[1])) and
                mn[0] != mn[1]))
            {
                const ops_to_test =
                    if (comptime zsl.meta.isNumeric(combination[0]))
                        .{"mul"}
                    else if (comptime zsl.meta.isNumeric(combination[1]))
                        .{ "mul", "div" }
                    else
                        .{ "add", "sub" };

                try executeTestBlock(allocator, rand, combination, ops_to_test, mn[0], mn[1]);
            }
        }
    }
}

fn executeTestBlock(
    allocator: std.mem.Allocator,
    rand: std.Random,
    comptime combination: [2]type,
    comptime ops: anytype,
    comptime m: usize,
    comptime n: usize,
) !void {
    inline for (ops) |op| {
        var B = if (comptime zsl.meta.isNumeric(combination[0]))
            tzsl.randomNumber(combination[0], rand)
        else
            try tzsl.matrix.randomMatrix(
                combination[0],
                allocator,
                rand,
                m,
                n,
                zsl.int.max(m, n) * 2,
            );
        defer tzsl.deinit(allocator, &B);

        var C = if (comptime zsl.meta.isNumeric(combination[1]))
            tzsl.randomNumber(combination[1], rand)
        else
            try tzsl.matrix.randomMatrix(
                combination[1],
                allocator,
                rand,
                m,
                n,
                zsl.int.max(m, n) * 2,
            );
        defer tzsl.deinit(allocator, &C);

        var D = if (comptime std.mem.eql(u8, op, "add"))
            try tzsl.matrix.correctApply2(zsl.meta.Numeric(combination[0]), allocator, m, n, B, C, zsl.numeric.addInto)
        else if (comptime std.mem.eql(u8, op, "sub"))
            try tzsl.matrix.correctApply2(zsl.meta.Numeric(combination[0]), allocator, m, n, B, C, zsl.numeric.subInto)
        else if (comptime std.mem.eql(u8, op, "mul"))
            try tzsl.matrix.correctApply2(zsl.meta.Numeric(combination[0]), allocator, m, n, B, C, zsl.numeric.mulInto)
        else
            try tzsl.matrix.correctApply2(zsl.meta.Numeric(combination[0]), allocator, m, n, B, C, zsl.numeric.divInto);
        defer D.deinit(allocator);

        const A = if (comptime std.mem.eql(u8, op, "add"))
            zsl.matrix.add(B, C)
        else if (comptime std.mem.eql(u8, op, "sub"))
            zsl.matrix.sub(B, C)
        else if (comptime std.mem.eql(u8, op, "mul"))
            zsl.matrix.mul(B, C)
        else
            zsl.matrix.div(B, C);

        tzsl.matrix.areEql(A, D) catch |e| {
            std.debug.print("Failed on A: {s} = B: {s} {s} C: {s}, case m = {}, n = {}\n", .{ @typeName(@TypeOf(A)), @typeName(combination[0]), op, @typeName(combination[1]), m, n });

            tzsl.matrix.printMatrix("A", A);
            if (comptime zsl.meta.isMatrix(@TypeOf(B))) tzsl.matrix.printMatrix("B", B) else std.debug.print("B: {}\n", .{B});
            if (comptime zsl.meta.isMatrix(@TypeOf(C))) tzsl.matrix.printMatrix("C", C) else std.debug.print("C: {}\n", .{C});
            tzsl.matrix.printMatrix("D", D);

            return e;
        };
    }
}
